-- Appended to transactional two-company test fixtures by run_local.py.
grant usage on schema masar_test to service_role;
grant insert on masar_test.results to service_role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
select masar_test.throws('select public.claim_document()','42501','browser cannot claim worker jobs');
select masar_test.throws($q$select public.bootstrap_company(auth.uid(),'denied','denied')$q$,'42501','browser cannot create privileged memberships');
select masar_test.throws($q$update public.documents set status='published'$q$,'42501','admin browser cannot publish unprocessed documents');
select masar_test.throws($q$insert into public.messages(company_id,conversation_id,role,content) values('10000000-0000-0000-0000-000000000001','c0000000-0000-0000-0000-000000000001','assistant','invented')$q$,'42501','browser cannot write assistant provenance');
reset role;
set local role service_role;
select masar_test.throws($q$select private.require_admin('a0000000-0000-0000-0000-000000000002')$q$,'42501','trusted RPC rechecks employee cannot administer');
select masar_test.throws($q$select public.provision_member('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','self',null,'company_admin')$q$,'42501','self role mutation denied in trusted RPC');
select masar_test.throws($q$select public.provision_member('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000005','wrong department','20000000-0000-0000-0000-000000000010','new_employee')$q$,'23503','cross-tenant membership FK enforced');
select public.provision_member('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000005','local test',null,'new_employee');
select masar_test.ok((select role='new_employee' from public.profiles where id='a0000000-0000-0000-0000-000000000005'),'trusted admin membership created');
select public.register_document('a0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001','local test',null,'company','text/plain',12,repeat('a',64),'10000000-0000-0000-0000-000000000001/local.txt','local.txt');
select masar_test.ok((select count(*)=0 from public.claim_document()),'job not claimable before upload finalized');
select public.mark_document_uploaded('a0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001',true);
select public.claim_document();
select masar_test.ok((select status='processing' and processing_token is not null from public.documents where id='e0000000-0000-0000-0000-000000000001'),'durable worker lease claimed');
select masar_test.ok((select count(*)=0 from public.claim_document()),'active job cannot be double claimed');
select masar_test.throws($q$select public.finish_document('e0000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','[]')$q$,'42501','wrong lease cannot publish');
select public.finish_document('e0000000-0000-0000-0000-000000000001',(select processing_token from public.documents where id='e0000000-0000-0000-0000-000000000001'),jsonb_build_array(jsonb_build_object('chunk_index',0,'content','VPN evidence from local test','embedding',jsonb_build_array(1)||to_jsonb(array_fill(0,array[1023])))));
select masar_test.ok((select status='published' and processing_token is null from public.documents where id='e0000000-0000-0000-0000-000000000001'),'processing publishes atomically');
select masar_test.throws($q$select public.manage_document('b0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001','archive')$q$,'P0002','other company admin cannot manage document');
reset role;
insert into storage.objects(bucket_id,name) select 'company-documents',storage_path from public.documents;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select masar_test.ok((select count(*)=1 from public.search_chunks('VPN')),'employee lexical retrieval sees allowed document');
select masar_test.ok((select count(*)=1 from public.search_chunks('VPN',('[1,'||array_to_string(array_fill(0,array[1023]),',')||']')::extensions.vector)),'employee vector retrieval sees allowed document');
select masar_test.ok((select count(*)=3 from storage.objects),'storage RLS permits only published company and department documents');
select masar_test.throws($q$insert into storage.objects(bucket_id,name) values('company-documents','forged')$q$,'42501','direct storage upload denied');
select masar_test.ok((select count(*)=0 from public.search_chunks('missingterm')),'retrieval refuses missing evidence');
reset role;
set local role service_role;
select masar_test.throws($q$select public.save_turn('a0000000-0000-0000-0000-000000000003','c0000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','question','answer','[]','not_found',null)$q$,'42501','other employee cannot write owner conversation');
select masar_test.throws($q$select public.save_turn('a0000000-0000-0000-0000-000000000002','c0000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','question','answer','[]','answered',null)$q$,'22023','answered turn requires sources');
select masar_test.throws(format($q$select public.save_turn('a0000000-0000-0000-0000-000000000002','c0000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','question','answer',%L,'answered','model')$q$,jsonb_build_array(jsonb_build_object('chunk_id',(select id from public.document_chunks where document_id='e0000000-0000-0000-0000-000000000001'),'document_id','e0000000-0000-0000-0000-000000000001','quote','invented quote'))::text),'42501','invented stored quote denied');
select public.save_turn('a0000000-0000-0000-0000-000000000002','c0000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','question','VPN evidence',jsonb_build_array(jsonb_build_object('chunk_id',(select id from public.document_chunks where document_id='e0000000-0000-0000-0000-000000000001'),'document_id','e0000000-0000-0000-0000-000000000001','quote','VPN evidence')),'answered','model');
select public.save_turn('a0000000-0000-0000-0000-000000000002','c0000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','question','VPN evidence','[]','not_found',null);
select masar_test.ok((select count(*)=2 from public.messages where turn_id='f0000000-0000-0000-0000-000000000001'),'same turn replay cannot duplicate messages');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
select masar_test.ok((select count(*)=0 from public.messages),'admin cannot read employee conversations');
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select masar_test.ok((select count(*)=1 from public.messages where role='assistant'),'owner can read allowed answer');
reset role;
set local role service_role;
select public.manage_document('a0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001','archive');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select masar_test.ok((select count(*)=0 from public.messages where role='assistant'),'revoked sources hide persisted assistant content');
select masar_test.ok((select count(*)=0 from public.search_chunks('VPN')),'archived content excluded from retrieval');
select masar_test.ok((select count(*)=2 from storage.objects),'archived original no longer readable');
reset role;
set local role service_role;
select masar_test.throws($q$select public.update_member('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001',null,'new_employee',false)$q$,'42501','admin cannot deactivate or demote own identity');
select masar_test.throws($q$select public.update_member('a0000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-000000000001',null,'new_employee',false)$q$,'P0002','admin cannot modify another tenant member');
select public.update_member('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000005',null,'new_employee',false);
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000005',true);
select masar_test.ok((select count(*)=0 from public.documents),'inactive identity sees no documents with still-valid JWT');
select masar_test.throws($q$select public.update_member(auth.uid(),auth.uid(),null,'company_admin',true)$q$,'42501','browser cannot activate or promote membership via RPC');
reset role;
set local role service_role;
select masar_test.throws($q$select public.edit_document('b0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','wrong',null,'company')$q$,'P0002','document ACL edits cannot cross tenant');
select public.edit_document('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','restricted source',null,'admins');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select masar_test.ok((select count(*)=1 from public.documents),'document ACL edit immediately revokes employee access');
reset role;
select 'TESTS_PASSED='||count(*) from masar_test.results;
rollback;
